// Generates src/norms/sources/johnson-webreport.ts from norm.py.
//
//   bun run scripts/generate-norms.ts
//
// Emits ONLY the 8 base (sex x age) strata; combined strata are derived at
// runtime (combineStrata). Fidelity is enforced by test/norms.test.ts
// (parseNormPy == gold JSON == this generated file). Do not hand-edit the output.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseNormPy, nsToNorms } from './parse-normpy';
import { labelFor } from '../src/norms/labels';
import type { DomainCode, FacetNumber } from '../src/types';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const PY = join(ROOT, 'norms-source', 'five-factor-e-norm.py');
const OUT = join(ROOT, 'src', 'norms', 'sources', 'johnson-webreport.ts');

const DOMAIN_ORDER: DomainCode[] = ['N', 'E', 'O', 'A', 'C'];

function num(n: number): string {
  // keep the exact source value; norm.py values have <=2 decimals.
  return String(n);
}

function renderNorms(ns: number[]): string {
  const norms = nsToNorms(ns);
  const domains = DOMAIN_ORDER.map((domain) => {
    const d = norms[domain];
    const facets = ([1, 2, 3, 4, 5, 6] as FacetNumber[])
      .map(
        (f) =>
          `          ${f}: { mean: ${num(d.facets[f].mean)}, sd: ${num(
            d.facets[f].sd
          )} }`
      )
      .join(',\n');
    return `      ${domain}: {
        domain: { mean: ${num(d.domain.mean)}, sd: ${num(d.domain.sd)} },
        facets: {
${facets}
        }
      }`;
  }).join(',\n');
  return `{
${domains}
    }`;
}

function main(): void {
  const py = readFileSync(PY, 'utf8');
  const strata = parseNormPy(py);

  const strataSrc = strata
    .map(
      (s) => `  {
    sex: '${s.sex}',
    ageBracket: '${s.ageBracket}',
    label: '${labelFor(s.sex, s.ageBracket)}',
    norms: ${renderNorms(s.ns)}
  }`
    )
    .join(',\n');

  const out = `// AUTO-GENERATED by scripts/generate-norms.ts — do not edit by hand.
// Source: five-factor-e (NeuroQuestAi) ipipneo/norm.py, 120-item strata,
//   credited to J. A. Johnson & D. Kholia. Regenerate:
//     bun run scripts/generate-norms.ts
// Fidelity (parseNormPy == gold JSON == this file) is enforced by
//   test/norms.test.ts. See norms-source/NOTICE.md for provenance.
import type { NormSet } from '../index';

export const johnsonWebReport: NormSet = {
  meta: {
    id: 'johnson-webreport',
    label: 'Johnson IPIP-NEO-120 online report norms',
    source: 'NeuroQuestAi/five-factor-e (ipipneo/norm.py)',
    provenanceNote:
      "Johnson's ONLINE IPIP-NEO report norms via five-factor-e; credited to J. A. Johnson & D. Kholia. NOT Johnson 2014 (JRP 51, 78-89). Per-stratum N is undocumented.",
    instrument: 'IPIP-NEO-120',
    version: '1.13.1',
    ageBrackets: ['lt21', 'a21_40', 'a41_60', 'gt60'],
    combinedMethod:
      'sex-unknown strata derived at runtime: mean = avg(male, female); SD = pooled sqrt(0.5*(sd_m^2+sd_f^2)+0.25*(mean_m-mean_f)^2) (deviation from five-factor-e, which averages SDs).'
  },
  strata: [
${strataSrc}
  ]
};
`;

  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, out);
  // eslint-disable-next-line no-console
  console.log(`wrote ${OUT} (${strata.length} base strata)`);
}

main();
